namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Exploration of abstract structures, quantities, and patterns through rigorous proof and analysis." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Investigation of matter, energy, and the fundamental forces that govern the natural world." },
            new() { Id = 4, Name = "English", Abbreviation = "ENGL", Description = "Critical reading, analytical writing, and the study of literature across cultures and periods." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Examination of past events, societies, and civilizations to understand the forces that shape the present." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has authored two textbooks on Python programming.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has authored two textbooks on Python programming.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", InstructorName = "Prof. Brian Torres", InstructorBio = "Prof. Torres spent a decade in industry building large-scale distributed databases before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is an award-winning educator whose research focuses on applied mathematics and mathematical modeling.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is an award-winning educator whose research focuses on applied mathematics and mathematical modeling.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 6, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an experimental physicist specializing in condensed matter. He has published over 50 peer-reviewed articles.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new() { Id = 7, CourseCode = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continuation of General Physics I.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Tue Lab 2:00–4:50 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is an experimental physicist specializing in condensed matter. He has published over 50 peer-reviewed articles.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 8, CourseCode = "ENGL 110", Title = "College Writing", Description = "Develop analytical reading and persuasive writing skills through essay composition and peer review workshops.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Prof. Sarah Mitchell", InstructorBio = "Prof. Mitchell is a published author and writing coach who has mentored hundreds of students in academic and creative writing.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, CourseCode = "ENGL 220", Title = "American Literature", Description = "Survey of major works in American literature from the colonial period to the present day.", Credits = 3, Schedule = "Mon/Wed 2:30–3:50 PM", InstructorName = "Prof. Sarah Mitchell", InstructorBio = "Prof. Mitchell is a published author and writing coach who has mentored hundreds of students in academic and creative writing.", DepartmentId = 4, DepartmentName = "English", IsFeatured = true },
            new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the late medieval period, covering political, social, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a historian of early modern Europe with a particular interest in cross-cultural exchange along trade routes.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 11, CourseCode = "HIST 102", Title = "World History since 1500", Description = "Continuation covering the early modern period through the contemporary era, including colonialism, revolutions, and globalization.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a historian of early modern Europe with a particular interest in cross-cultural exchange along trade routes.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 12, CourseCode = "CS 450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, decision trees, and practical applications using real-world datasets.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma leads the university's AI research lab and has contributed to several open-source ML frameworks.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

